{
    static const uint32_t s[] = { 0x30FB, 0xFF1A, 0xFF1B, 0xFF65, 0x203C, 0x2047, 0x2048, 0x2049, 0xFF01, 0xFF1F };
    return LB_IN(c, s);
}
